    const [currentStep, setCurrentStep] = useState(args.currentStep);

    const handleGoToStep = (event: CustomEvent<number>) => {
        setCurrentStep(event.detail);
        action("goToStep")(event);
    };

    const styles = {
        height: "600px",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        color: "white"
