                <div slot="additional-header-actions">Additional Header Action
                                        </div>
                <div slot="step-content" style={{ height: "100%", overflow: "scroll" }}>
                    {currentStep === 0 && (
                        <div style={{ backgroundColor: "gray", ...styles }}>
