                        </div>
                    )}
                    {currentStep === 1 && (
                        <div
                            style={{ backgroundColor: "black", ...styles }}
                        >
                            Step 2 Content
                        </div>
                    )}
                </div>
            </KvWizard>
        </div>
    );
};

